package com.game_manager.gm.report;
import com.game_manager.gm.common.entity.BaseEntity; import jakarta.persistence.*; import java.util.UUID; import lombok.*; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes;
@Entity @Table(name="report_templates") @Getter @Setter @NoArgsConstructor public class ReportTemplate extends BaseEntity {@JdbcTypeCode(SqlTypes.CHAR) @Column(name="owner_id",nullable=false,length=36) private UUID ownerId;@Column(nullable=false,length=100) private String name;@Column(name="definition_key",nullable=false,length=50) private String definitionKey;@Enumerated(EnumType.STRING) @Column(nullable=false,length=10) private ReportFormat format;@Column(name="filters_json",nullable=false,columnDefinition="TEXT") private String filtersJson;}
